 \newcommand{\totald}[3][]{\frac{\mathrm{d}^{#1} #2}{\mathrm{d} #3^{#1}}}
 \newcommand{\verts}[1]{\left\vert\,{#1}\,\right\vert}$ 
 $\ds{\underline{"Outside"}\,\,\, Volume\
{\Large\cal V}_{\mrm{out}} \pars{~\mbox{Cylindrical Coordintaes}~}}$ . 
 Hereafter,  $\ds{\bracks{\cdots}}$  is an
 Iverson Bracket . 
 Namely,  $\ds{\bracks{P} =
\left\{\begin{array}{rcl}
\ds{1} & \mbox{if}\ P\ \mbox{is}\ true.
\\[1mm]
\ds{0} & \,\,\,\,\,\mbox{if}\ P\ \mbox{is}\ false.
\end{array}\right.}$ 

 \begin{align}
{\Large\cal V}_{\mrm{out}} & \equiv
\bbox[5px,#ffd]{\iiint_{\mathbb{R}^{3}}\bracks{x^{2} + y^{2} > 1}\bracks{x^{2} + y^{2} + z^{2} < 4}
\dd^{3}\vec{r}}
\\[5mm] & =
\iiint_{\mathbb{R}^{3}}\bracks{\rho^{2} > 1}
\bracks{\rho^{2} + z^{2} < 4}
\rho\,\dd\rho\,\dd \phi\,\dd z
\\[5mm] & =
\iiint_{\mathbb{R}^{3}}
\bracks{1 < \rho^{2} < 4 - z^{2}}
\rho\,\dd\rho\,\dd \phi\,\dd z
\\[5mm] & =
\iiint_{\mathbb{R}^{3}}
\bracks{1 < 4 - z^{2}}
\bracks{1 < \rho < \root{4 - z^{2}}}
\\[2mm] &\ \rho\,\dd\rho\,\dd \phi\,\dd z
\\[5mm] & =
\iiint_{\mathbb{R}^{3}}
\bracks{\verts{z} < \root{3}}
\bracks{1 < \rho < \root{4 - z^{2}}}
\\[2mm] & \rho\,\dd\rho\,\dd \phi\,\dd z
\\[5mm] & =
2\pi\int_{-\root{3}}^{\root{3}}
\int_{1}^{\root{4 - z^{2}}}\rho\,\dd\rho\,\dd z
\\[5mm] & =
\pi\int_{-\root{3}}^{\root{3}}\pars{3 - z^{2}}\dd z
\\[5mm] & =
\bbx{4\root{3}\pi} \approx 21.7656 \\ &
\end{align} 
