 - {{15\left( {2k} \right)} \over {22}}} \right\} + j} \right) =  \hfill \cr  
   = {{11} \over {719}}\left( {\left\{ {{{11 - 8k} \over {22}}} \right\} + j} \right) 
 = s_{\,u} (k,j) \hfill \cr}  \hfill & {{\rm upper}\;{\rm Tr}{\rm .}} \hfill  \cr  
   \matrix{ 
  {1 \over m}\left\{ {{1 \over 2} + {m \over 2} + q} \right\} + {j \over m}
 = {{11} \over {719}}\left( {\left\{ {{1 \over 2} + {{719} \over {22}}
 + {{15\left( {2k + 1} \right)} \over {22}}} \right\} + j} \right) =  \hfill \cr 
   = {{11} \over {719}}\left( {\left\{ {{{19 + 8k} \over {22}}} \right\} + j} \right)
 = s_{\,d} (k,j) \hfill \cr}  \hfill & {{\rm lower}\;{\rm Tr}{\rm .}} \hfill  \cr 
 } } \right.
$$ 
 Since
 $$
\eqalign{
  & {{11} \over {719}}\left( {\left\{ {{{11 - 8k} \over {22}}} \right\} + j} \right)
 = {1 \over {2 \cdot 719}}\left( {22\left\{ {{{11 + 14k} \over {22}}} \right\} + 22j} \right)  \cr 
  & 22\left\{ {{{11 + 14k} \over {22}}} \right\}\quad  \Rightarrow \quad 11 + 14k
 = 2n + 1\quad \left( {\bmod 22} \right)\quad  \Rightarrow   \cr  
  &  \Rightarrow \quad 5 + 7k = n\quad \left( {\bmod 11} \right)\quad 
  \Rightarrow \quad 7k \equiv n + 5\quad \left( {\bmod 11} \right) \cr}  
$$ 
and
 $$ 
\eqalign{ 
  & {{11} \over {719}}\left( {\left\{ {{{19 + 8k} \over {22}}} \right\} + j} \right) 
 = {1 \over {2 \cdot 719}}\left( {22\left\{ {{{19 + 8k} \over {22}}} \right\} + 22j} \right)  \cr  
  & 22\left\{ {{{19 + 8k} \over {22}}} \right\}\quad  \Rightarrow \quad 19 + 8k 
 = 2n + 1\quad \left( {\bmod 22} \right)\quad  \Rightarrow   \cr  
  &  \Rightarrow \quad 9 + 4k = n\quad \left( {\bmod 11} \right)\quad  \Rightarrow 
 \quad 4k \equiv n + 2\quad \left( {\bmod 11} \right) \cr}  
$$ 
then the {Independent Residues theorem]( https://en.wikipedia.org/wiki/Residue_number_system ) 
assures us that the the two relations above are bijections between 
 $$\left[ {0 \le k \le 10} \right] \Leftrightarrow \left[ {0 \le n \le 10} \right]$$ 
