4\pi^{2}\
\underbrace{\mrm{P.V.}\int_{0}^{\infty}{\dd x \over x^{3} - 1}
\,\dd x}_{\ds{-\,{\root{3} \over 9}\,\pi}}\  +\
{4\pi^{3} \over 3}\,\ic
\end{align} 

 \begin{align}
