\\[2mm] = &\
{-\,\pars{4/27}\pars{3\root{3} - 5\ic}\pi^{3} -
4\pi^{2}\pars{-\root{3}\pi/9} - 4\pi^{3}\ic/3 \over -4\pi\ic}
\\[2mm] & =
